def is_acronym(words: list[str], s: str) -> bool:
    # An acronym must have the same length as the number of words provided
    if len(words) != len(s):
        return False

    # Check if the i-th character of s matches the first character of the i-th word
    for i in range(len(words)):
        if words[i][0] != s[i]:
            return False

    return True
```

