def findMissingAndRepeatedValues(grid):
    n = len(grid)
    count = [0] * (n * n + 1)

    # Count the occurrences of each number in the grid
    for row in grid:
        for val in row:
            count[val] += 1

    a = -1
    b = -1

    # Identify the repeated number (a) and the missing number (b)
    for i in range(1, n * n + 1):
        if count[i] == 2:
            a = i
        elif count[i] == 0:
            b = i

    return [a, b]
