import sys

def solve():
    # Read the number of sheets
    try:
        line1 = sys.stdin.readline()
        if not line1:
            return
        n = int(line1.strip())
    except ValueError:
        return

    # Create a 100x100 boolean grid to track covered unit squares
    # grid[x][y] corresponds to the square [x, x+1] x [y, y+1]
    covered = [[False for _ in range(100)] for _ in range(100)]

    for _ in range(n):
        try:
            a, b, c, d = map(int, sys.stdin.readline().split())
            # Mark all unit squares covered by this rectangle as True
            for x in range(a, b):
                for y in range(c, d):
                    covered[x][y] = True
        except ValueError:
            break

    # Count the number of True values in the grid
    area = 0
    for x in range(100):
        for y in range(100):
            if covered[x][y]:
                area += 1

    print(area)

if __name__ == "__main__":
    solve()
```

