import sys

def solve():
    # Read input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    h = int(input_data[1])
    w = int(input_data[2])

    tiles = []
    idx = 3
    for _ in range(n):
        a = int(input_data[idx])
        b = int(input_data[idx+1])
        tiles.append((a, b))
        idx += 2

    # Grid represented as a bitmask or 2D array
    # Since H, W <= 10, a tuple of tuples or a flat array works
    grid = [[False for _ in range(w)] for _ in range(h)]

    def can_place(r, c, dh, dw, current_grid):
        if r + dh > h or c + dw > w:
            return False
        for i in range(r, r + dh):
            for j in range(c, c + dw):
                if current_grid[i][j]:
                    return False
        return True

    def fill(r, c, dh, dw, current_grid, val):
        for i in range(r, r + dh):
            for j in range(c, c + dw):
                current_grid[i][j] = val

    def backtrack(tiles_used_mask, current_grid):
        # Find first empty cell
        first_empty = None
        for r in range(h):
            for c in range(w):
                if not current_grid[r][c]:
                    first_empty = (r, c)
                    break
            if first_empty: break

        if not first_empty:
            return True

        r, c = first_empty

        for i in range(n):
            if not (tiles_used_mask & (1 << i)):
                a, b = tiles[i]
                # Try both orientations (a x b) and (b x a)
                orientations = set([(a, b), (b, a)])
                for dh, dw in orientations:
                    if can_place(r, c, dh, dw, current_grid):
                        fill(r, c, dh, dw, current_grid, True)
                        if backtrack(tiles_used_mask | (1 << i), current_grid):
                            return True
                        fill(r, c, dh, dw, current_grid, False)
        return False

    if backtrack(0, grid):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
```

To solve this problem, we can treat the indices as nodes in a graph. An edge exists between index `i` and `j` if `gcd(nums[i], nums[j]) > 1`. Instead of directly building edges between indices (which would be $O(N^2)$), we can use the prime factors of each number as intermediate nodes. 

If a number `x` has a prime factor `p`, we can connect `x` to `p`. If two numbers share a prime factor, they belong to the same connected component. We can use a Disjoint Set Union (DSU) to group all numbers that share at least one common prime factor. Finally, we check if all numbers `nums[i]` with `nums[i] > 1` belong to the same component. Note that numbers equal to 1 cannot be part of any traversal (unless the array size is 1).

```python
def can_traverse_all_pairs(nums: list[int]) -> bool:
    if len(nums) == 1:
        return True

    max_num = max(nums)
    if min(nums) == 1:
        return False

    # DSU structure
    parent = list(range(max_num + 1))
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Sieve to find prime factors for each number
    min_prime = list(range(max_num + 1))
    for i in range(2, int(max_num**0.5) + 1):
        if min_prime[i] == i:
            for j in range(i*i, max_num + 1, i):
                if min_prime[j] == j:
                    min_prime[j] = i

    # For each number, union it with its prime factors
    for x in nums:
        temp = x
        while temp > 1:
            p = min_prime[temp]
            union(x, p)
            while temp % p == 0:
                temp //= p

    # Check if all numbers in nums share the same root
    root = find(nums[0])
    for i in range(1, len(nums)):
        if find(nums[i]) != root:
            return False

    return True
```

