    for left in range(n):
        counts = {}
        for right in range(left, n):
            char = s[right]
            counts[char] = counts.get(char, 0) + 1

            # If any character exceeds 2 occurrences, break the inner loop
            if counts[char] > 2:
                break

            # Calculate length and update max_len
            current_len = right - left + 1
            if current_len > max_len:
                max_len = current_len

