To solve this problem, we need to determine the winner of the game using minimax search with memoization. Given the small grid size (3x3), the state space is manageable. 

A state can be represented by:
1. Which cells are white, red, or blue.
2. The current scores of Takahashi and Aoki.
3. Whose turn it is.

Since the total number of turns is at most 9, we can use recursion to explore all possible game paths to see if the first player (Takahashi) can force a win.

```python
import sys

def solve():
    grid = []
    for _ in range(3):
        grid.extend(map(int, sys.stdin.readline().split()))

    # Lines that define a win: 3 rows, 3 columns, 2 diagonals
    lines = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8), # rows
        (0, 3, 6), (1, 4, 7), (2, 5, 8), # cols
        (0, 4, 8), (2, 4, 6)             # diagonals
    ]

    memo = {}

    def get_winner(mask, red_mask, blue_mask, score_t, score_a, turn):
        state = (mask, red_mask, blue_mask, score_t, score_a, turn)
        if state in memo: return memo[state]

        # Check if previous move created a line
        prev_color = blue_mask if turn == 0 else red_mask
        for l1, l2, l3 in lines:
            if (prev_color & (1 << l1)) and (prev_color & (1 << l2)) and (prev_color & (1 << l3)):
                return (turn == 1) # If Takahashi (turn 0) moved, return True

        # Check if board full
        if mask == 0:
            return score_t > score_a

        can_win = False
        if turn == 0: # Takahashi's turn (maximize)
            for i in range(9):
                if mask & (1 << i):
                    if get_winner(mask ^ (1 << i), red_mask | (1 << i), blue_mask, score_t + grid[i], score_a, 1):
                        can_win = True
                        break
        else: # Aoki's turn (minimize for Takahashi)
            can_win = True
            for i in range(9):
                if mask & (1 << i):
                    if not get_winner(mask ^ (1 << i), red_mask, blue_mask | (1 << i), score_t, score_a + grid[i], 0):
                        can_win = False
                        break

        memo[state] = can_win
        return can_win

    # Initial state: 9 cells white (mask 0x1FF), turn 0
    if get_winner(0x1FF, 0, 0, 0, 0, 0):
        print("Takahashi")
    else:
        print("Aoki")

if __name__ == '__main__':
    solve()
