def findPrimePairs(n: int):
    if n < 4:
        return []

    # Use a sieve to find all primes up to n
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False
    for p in range(2, int(n**0.5) + 1):
        if primes[p]:
            for i in range(p * p, n + 1, p):
                primes[i] = False

    result = []
    # Iterate x up to n/2 to ensure x <= y
    # x + y = n => y = n - x. Since x <= y, x <= n - x => 2x <= n => x <= n/2
    for x in range(2, n // 2 + 1):
        if primes[x] and primes[n - x]:
            result.append([x, n - x])

    return result
