def solve(wordsContainer, wordsQuery):
    # A Trie node will store:
    # 1. 'children': map of characters to child nodes
    # 2. 'best_idx': the index of the best word found so far that passes through this node
    # The "best" word is defined by: shortest length, then earliest index.

    trie = {}

    # Pre-process: Find the global "best" word (shortest length, then earliest index)
    # to serve as the default answer if no suffix matches exist.
    best_overall_idx = 0
    for i in range(1, len(wordsContainer)):
        if len(wordsContainer[i]) < len(wordsContainer[best_overall_idx]):
            best_overall_idx = i
        elif len(wordsContainer[i]) == len(wordsContainer[best_overall_idx]):
            if i < best_overall_idx:
                best_overall_idx = i

    # Insert reversed words into the Trie
    for i, word in enumerate(wordsContainer):
        node = trie
        if 'best_idx' not in node:
            node['best_idx'] = i
        else:
            curr_best = node['best_idx']
            if len(word) < len(wordsContainer[curr_best]):
                node['best_idx'] = i
            elif len(word) == len(wordsContainer[curr_best]):
                if i < curr_best:
                    node['best_idx'] = i

        # Traverse/Build Trie with reversed characters
        for char in reversed(word):
            if char not in node:
                node[char] = {}
            node = node[char]

            # Update best_idx for this path
            if 'best_idx' not in node:
                node['best_idx'] = i
            else:
                curr_best = node['best_idx']
                if len(word) < len(wordsContainer[curr_best]):
                    node['best_idx'] = i
                elif len(word) == len(wordsContainer[curr_best]):
                    if i < curr_best:
                        node['best_idx'] = i

    # Process queries
    ans = []
    for query in wordsQuery:
        node = trie
        # Traverse as far as the reversed query matches the Trie
        for char in reversed(query):
            if char in node:
                node = node[char]
            else:
                break
        ans.append(node['best_idx'])

    return ans
