        arr = list(arr)
        count = 0
        for i in range(n):
            for j in range(i + 1, n):
                if arr[i] > arr[j]:
                    count += 1
        return count

    # Try all row permutations P and column permutations Q
    # Grid A's row i moves to row P[i], column j moves to column Q[j]
    # New grid A'[r][c] = A[P^-1[r]][Q^-1[c]]
    # We want A'[r][c] == B[r][c] for all r, c

