import itertools

def solve(a, b, c):
    # First, simplify: if one string is a substring of another, remove it.
    def is_substring(s1, s2):
        return s1 in s2

    strings = sorted(list(set([a, b, c])), key=len, reverse=True)
    temp = []
    for i in range(len(strings)):
        is_sub = False
        for j in range(len(strings)):
            if i != j and is_substring(strings[i], strings[j]):
                is_sub = True
                break
        if not is_sub:
            temp.append(strings[i])
    strings = temp

    # Function to merge two strings s1 and s2 optimally
    def merge(s1, s2):
        # Find max overlap where s2 starts at the end of s1
        for length in range(min(len(s1), len(s2)), 0, -1):
            if s1.endswith(s2[:length]):
                return s1 + s2[length:]
        return s1 + s2

    # Since there are at most 3 strings, test all permutations
    ans = None
    for p in itertools.permutations(strings):
        # Merge order p[0] -> p[1] -> p[2]
        res = merge(p[0], merge(p[1], p[2]))

        if ans is None:
            ans = res
        else:
            if len(res) < len(ans):
                ans = res
            elif len(res) == len(ans):
                if res < ans:
                    ans = res
    return ans
