To solve this problem, we need to determine if there is exactly one person who can be the "strongest." Since the superiority relation defines a total ordering (a tournament graph), a person is the strongest if and only if they have no one stronger than them (i.e., their "in-degree" in the relation sense is 0).

We can represent the relationships using an adjacency matrix (or a reachability matrix) where `adj[i][j]` is true if person `i` is stronger than person `j`. We initialize this based on the input and use the Floyd-Warshall algorithm to compute the transitive closure. A person `i` can be the strongest if there is no person `j` such that `j` is stronger than `i`. After processing all constraints, we check how many people have no one stronger than them.

Here is the implementation:

```python
import sys

def solve():
    # Read N and M
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # reach[i][j] will be True if person i is stronger than person j
    # People are 1-indexed, we'll use 0-indexed internally
    reach = [[False for _ in range(N)] for _ in range(N)]

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        reach[u][v] = True
        idx += 2

    # Floyd-Warshall to find reachability (transitive closure)
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if reach[i][k] and reach[k][j]:
                    reach[i][j] = True

    # A person i is a candidate for strongest if no one is stronger than them.
    # Person j is stronger than person i if reach[j][i] is True.
    candidates = []
    for i in range(N):
        is_strongest_possible = True
        for j in range(N):
            if i == j:
                continue
            # If j is known to be stronger than i, i cannot be the strongest
            if reach[j][i]:
                is_strongest_possible = False
                break

        if is_strongest_possible:
            candidates.append(i + 1)

    # Output the result
    if len(candidates) == 1:
        print(candidates[0])
    else:
        print(-1)

if __name__ == '__main__':
    solve()
```

To solve this problem, we first sort the array. The median index for an array of length $n$ (where we pick the larger of the two middle elements) is `mid = n // 2`. 

After sorting, if the current median `nums[mid]` is less than $k$, we must increase `nums[mid]` and all elements to its right that are smaller than `k` until they reach $k$. Conversely, if `nums[mid]` is greater than $k$, we must decrease `nums[mid]` and all elements to its left that are greater than $k$ until they reach $k$.

```python
def minOperationsToMakeMedian(nums, k):
    nums.sort()
    n = len(nums)
    mid = n // 2

    operations = 0

    # Target is nums[mid] == k.
    # Current median is nums[mid].

    # If the current median is smaller than k, we need to increase the median
    # and potentially other elements to the right to maintain sorted order/median property.
    if nums[mid] < k:
        operations += (k - nums[mid])
        for i in range(mid + 1, n):
            if nums[i] < k:
                operations += (k - nums[i])
            else:
                break

    # If the current median is larger than k, we need to decrease the median
    # and potentially other elements to the left.
    elif nums[mid] > k:
        operations += (nums[mid] - k)
        for i in range(mid - 1, -1, -1):
            if nums[i] > k:
                operations += (nums[i] - k)
            else:
                break

    return operations
```

To solve this problem, we use dynamic programming. We need to construct an array with `zero` 0s and `one` 1s such that no sequence of identical digits exceeds `limit`.

Let `dp[i][j][k][0]` represent the number of ways to form an array with `i` zeros and `j` ones, ending with a sequence of `k` zeros (where $1 \le k \le \text{limit}$).
Let `dp[i][j][k][1]` represent the number of ways to form an array with `i` zeros and `j` ones, ending with a sequence of `k` ones (where $1 \le k \le \text{limit}$).

```python
def countStableArrays(zero, one, limit):
    MOD = 10**9 + 7

    # dp[i][j][k][0] -> i zeros, j ones, ends with k zeros
    # dp[i][j][k][1] -> i zeros, j ones, ends with k ones
    dp = [[[[0, 0] for _ in range(limit + 1)] for _ in range(one + 1)] for _ in range(zero + 1)]

    # Base cases: array of length 1
    for k in range(1, min(zero, limit) + 1):
        dp[k][0][k][0] = 1
    for k in range(1, min(one, limit) + 1):
        dp[0][k][k][1] = 1

    for i in range(zero + 1):
        for j in range(one + 1):
            if i == 0 and j == 0: continue
            for k in range(1, limit + 1):
                # Transition for ending in 0 (dp[i][j][k][0])
                if k == 1:
                    # Previous must have ended in 1s
                    for prev_k in range(1, limit + 1):
                        if j > 0:
                            dp[i][j][1][0] = (dp[i][j][1][0] + dp[i][j-1][prev_k][1]) % MOD
                else:
                    # Can only come from i-1 zeros ending in k-1 zeros
                    if i > 0:
                        dp[i][j][k][0] = dp[i-1][j][k-1][0]

                # Transition for ending in 1 (dp[i][j][k][1])
                if k == 1:
                    # Previous must have ended in 0s
                    for prev_k in range(1, limit + 1):
                        if i > 0:
                            dp[i][j][1][1] = (dp[i][j][1][1] + dp[i-1][j][prev_k][0]) % MOD
                else:
                    # Can only come from j-1 ones ending in k-1 ones
                    if j > 0:
                        dp[i][j][k][1] = dp[i][j-1][k-1][1]

    ans = 0
    for k in range(1, limit + 1):
        ans = (ans + dp[zero][one][k][0] + dp[zero][one][k][1]) % MOD

    return ans
```

To solve this problem efficiently, we observe that a string $S$ is "good" if $S[i] \neq S[i+1]$ for all $i$ in the range. This condition is equivalent to saying that the adjacent differences are all $1$ (if we consider $S$ as integers). 

We can define an auxiliary array $D$ where $D[i] = 1$ if $S[i] \neq S[i+1]$, and $D[i] = 0$ otherwise, for $1 \leq i < N$. A substring $S[L..R]$ is good if $D[i] = 1$ for all $L \leq i < R$. Using a Fenwick tree (or Segment Tree) to track where $D[i] = 0$ allows us to answer range queries in $O(\log N)$ time. Flipping a range $[L, R]$ in $S$ keeps the relation $S[i] \neq S[i+1]$ unchanged for $L \leq i < R$, but flips the relation at the boundaries $L-1$ and $R$.

```python
import sys

def solve():
    input = sys.stdin.read().split()
    N = int(input[0])
    Q = int(input[1])
    S = list(map(int, list(input[2])))

    # D[i] = 1 if S[i] != S[i+1] else 0
    # Condition: In range [L, R], D[i] must be 1 for all i in [L, R-1]
    # We track indices where S[i] == S[i+1] using a Fenwick tree
    bad = [0] * (N + 1)

    def update_bad(i, val):
        if i < 1 or i >= N: return
        idx = i
        while idx <= N:
            bit[idx] += val
            idx += idx & (-idx)

    def query_bad(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & (-i)
        return s

    bit = [0] * (N + 1)
    for i in range(N - 1):
        if S[i] == S[i+1]:
            bad[i+1] = 1
            update_bad(i+1, 1)

    # Lazy flip array for S
    # Since we only need to know flips at boundary, use a Fenwick tree for S
    bit_s = [0] * (N + 1)
    def update_s(i, val):
        while i <= N:
            bit_s[i] += val
            i += i & (-i)
    def get_s(i):
        s = 0
        while i > 0:
            s += bit_s[i]
            i -= i & (-i)
        return s % 2

    ptr = 3
    results = []
    for _ in range(Q):
        t = int(input[ptr])
        l = int(input[ptr+1])
        r = int(input[ptr+2])
        ptr += 3

        if t == 1:
            # Flip range [l, r]
            # S[i] == S[i+1] status changes at boundaries l-1 and r
            for boundary in [l - 1, r]:
                if 1 <= boundary < N:
                    val = 1 if (get_s(boundary) == get_s(boundary + 1)) else -1
                    if bad[boundary]:
                        update_bad(boundary, -1)
                        bad[boundary] = 0
                    else:
                        update_bad(boundary, 1)
                        bad[boundary] = 1
            update_s(l, 1)
            update_s(r + 1, 1)
        else:
            if l == r:
                results.append("Yes")
            else:
                if query_bad(r - 1) - query_bad(l - 1) == 0:
                    results.append("Yes")
                else:
                    results.append("No")

    sys.stdout.write("\n".join(results) + "\n")

if __name__ == '__main__':
    solve()
```

