import sys

def solve():
    # Use fast I/O
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    M = int(input_data[2])

    ops = []
    idx = 3
    for _ in range(M):
        ops.append((int(input_data[idx]), int(input_data[idx+1]), int(input_data[idx+2])))
        idx += 3

    # Track the last operation time per row/col
    # row_last[r] = (time, color)
    row_last = {}
    col_last = {}

    # Process in reverse to determine the final color of each cell
    for i in range(M - 1, -1, -1):
        t, a, x = ops[i]
        if t == 1:
            if a not in row_last:
                row_last[a] = (i, x)
        else:
            if a not in col_last:
                col_last[a] = (i, x)

    # Cells:
    # 1. Total cells = H * W
    # 2. Count occupied cells by specific row/col operations
    # A cell at (r, c) gets color from row if row_last[r].time > col_last[c].time

    row_count = len(row_last)
    col_count = len(col_last)

    # Colors and their cell counts
    color_map = {}

    # Cells definitely occupied by row operations
    # If a row was colored at time T_r, it loses columns covered by later column ops
    for r, (tr, xr) in row_last.items():
        used_cols = 0
        for c, (tc, xc) in col_last.items():
            if tc > tr:
                used_cols += 1

        count = W - used_cols
        if count > 0:
            color_map[xr] = color_map.get(xr, 0) + count

    # Cells definitely occupied by column operations
    for c, (tc, xc) in col_last.items():
        used_rows = 0
        for r, (tr, xr) in row_last.items():
            if tr > tc:
                used_rows += 1

        count = H - used_rows
        if count > 0:
            color_map[xc] = color_map.get(xc, 0) + count

    # Cells left with color 0
    # Initial color 0 exists if not all rows or not all columns are covered
    occupied_rows = row_count
    occupied_cols = col_count
    total_covered = (occupied_rows * W) + (occupied_cols * H) - (occupied_rows * occupied_cols)
    remaining_zeros = (H * W) - total_covered

    if remaining_zeros > 0:
        color_map[0] = color_map.get(0, 0) + remaining_zeros

    # Format Output
    sorted_colors = sorted(color_map.keys())
    print(len(sorted_colors))
    for color in sorted_colors:
        print(f"{color} {color_map[color]}")

if __name__ == '__main__':
