import sys
from collections import deque
from itertools import combinations

def solve():
    # Read H, W, T
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    T = int(input_data[2])
    grid = input_data[3:]

    start = None
    goal = None
    candies = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'G':
                goal = (r, c)
            elif grid[r][c] == 'o':
                candies.append((r, c))

    nodes = [start] + candies + [goal]
    n = len(nodes)

    # BFS to find shortest paths between all special points
    def bfs(start_node):
        dist = [[-1] * W for _ in range(H)]
        dist[start_node[0]][start_node[1]] = 0
        queue = deque([start_node])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    queue.append((nr, nc))
        return dist

    adj = [[-1] * n for _ in range(n)]
    for i in range(n):
        dists = bfs(nodes[i])
        for j in range(n):
            adj[i][j] = dists[nodes[j][0]][nodes[j][1]]

    # DP with bitmask
    # candies are nodes 1 to len(candies)
    num_c = len(candies)
    # dp[mask][i] is min distance to have visited candies in mask, ending at node i
    # mask represents visited candies, i is the index in 'nodes' (0: start, 1..num_c: candies, n-1: goal)
    dp = [[float('inf')] * (num_c + 1) for _ in range(1 << num_c)]

    # Init: starting from S to each candy
    for i in range(num_c):
        d = adj[0][i + 1]
        if d != -1:
            dp[1 << i][i + 1] = d

    # Transitions
    for mask in range(1, 1 << num_c):
        for u in range(1, num_c + 1):
            if dp[mask][u] == float('inf'): continue
            for v in range(1, num_c + 1):
                if not (mask & (1 << (v - 1))):
                    d = adj[u][v]
                    if d != -1:
                        new_mask = mask | (1 << (v - 1))
                        if dp[new_mask][v] > dp[mask][u] + d:
                            dp[new_mask][v] = dp[mask][u] + d

    # Final check: Goal
    ans = -1
    if adj[0][n - 1] != -1 and adj[0][n - 1] <= T:
        ans = 0

    for mask in range(1 << num_c):
        for u in range(1, num_c + 1):
            if dp[mask][u] != float('inf'):
                d = adj[u][n - 1]
                if d != -1 and dp[mask][u] + d <= T:
                    count = bin(mask).count('1')
                    if count > ans:
                        ans = count

    print(ans)

if __name__ == '__main__':
    solve()
