def minEqualSum(nums1, nums2):
    def get_sum_and_zeros(nums):
        current_sum = 0
        zero_count = 0
        for x in nums:
            if x == 0:
                zero_count += 1
            else:
                current_sum += x
        return current_sum, zero_count

    sum1, zeros1 = get_sum_and_zeros(nums1)
    sum2, zeros2 = get_sum_and_zeros(nums2)

    # Each zero must be at least 1.
    # min_sum1 = sum1 + zeros1
    # min_sum2 = sum2 + zeros2
    min_sum1 = sum1 + zeros1
    min_sum2 = sum2 + zeros2

    # If an array has no zeros, its sum is fixed.
    # If it has zeros, it can achieve any sum >= min_sum.

    if zeros1 == 0 and zeros2 == 0:
        return sum1 if sum1 == sum2 else -1

    if zeros1 == 0:
        return sum1 if sum1 >= min_sum2 else -1

    if zeros2 == 0:
        return sum2 if sum2 >= min_sum1 else -1

    # If both have zeros, the minimum possible equal sum is the maximum of the two minimums.
    return max(min_sum1, min_sum2)
