def punishmentNumber(n: int) -> int:
    def can_partition(target_str: str, target_val: int) -> bool:
        if not target_str and target_val == 0:
            return True
        if target_val < 0:
            return False

        for i in range(1, len(target_str) + 1):
            left_part = int(target_str[:i])
            if can_partition(target_str[i:], target_val - left_part):
                return True
        return False

    total_punishment = 0
    for i in range(1, n + 1):
        square_val = i * i
        if can_partition(str(square_val), i):
            total_punishment += square_val

    return total_punishment
