To solve this problem, we need to find the shortest transformation path between any two characters. This is a classic "all-pairs shortest path" problem on a graph where lowercase English characters ('a'-'z') are nodes. Since there are only 26 characters, we can use the Floyd-Warshall algorithm to precompute the minimum cost to transform any character `i` to character `j`.

```python
def minimumCost(source, target, original, changed, cost):
    # Initialize the distance matrix with infinity
    # There are 26 possible lowercase English characters
    inf = float('inf')
    dist = [[inf] * 26 for _ in range(26)]

    # Distance to self is 0
    for i in range(26):
        dist[i][i] = 0

    # Populate the initial graph with given costs
    for o, c, val in zip(original, changed, cost):
        u = ord(o) - ord('a')
        v = ord(c) - ord('a')
        dist[u][v] = min(dist[u][v], val)

    # Floyd-Warshall algorithm to find all-pairs shortest paths
    for k in range(26):
        for i in range(26):
            if dist[i][k] != inf:
                for j in range(26):
                    if dist[k][j] != inf:
                        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    total_cost = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue

        u = ord(s_char) - ord('a')
        v = ord(t_char) - ord('a')

        if dist[u][v] == inf:
            return -1

        total_cost += dist[u][v]

    return total_cost
```

To solve this problem, we need to count substrings where each character appears exactly `k` times and the difference between adjacent characters is at most 2. 

Because the alphabet constraint (adjacent characters diff $\le 2$) is local, we can split the string into segments where this condition holds. Within each segment, we can iterate over the number of distinct characters $m$ allowed in a valid substring (there can only be 1 to 26 distinct characters). For a fixed $m$, the length of the valid substring must be exactly $m \times k$. We can then use a sliding window approach to count how many substrings of length $m \times k$ satisfy the condition that each of the $m$ characters appears exactly $k$ times.

```python
def countCompleteSubstrings(word: str, k: int) -> int:
    n = len(word)
    ans = 0

    # Split the word into segments where adjacent characters have diff <= 2
    segments = []
    start = 0
    for i in range(1, n):
        if abs(ord(word[i]) - ord(word[i-1])) > 2:
            segments.append(word[start:i])
            start = i
    segments.append(word[start:])

    def count_k_freq(s, m):
        """Count substrings of length m*k where each char appears exactly k times."""
        count = 0
        target_len = m * k
        if len(s) < target_len:
            return 0

        freq = {}
        # Sliding window of size m * k
        for i in range(len(s)):
            char = s[i]
            freq[char] = freq.get(char, 0) + 1

            if i >= target_len:
                out_char = s[i - target_len]
                freq[out_char] -= 1
                if freq[out_char] == 0:
                    del freq[out_char]

            if i >= target_len - 1:
                if len(freq) == m and all(val == k for val in freq.values()):
                    count += 1
        return count

    for seg in segments:
        # A valid substring can have m distinct characters, where 1 <= m <= 26
        # and m*k <= len(seg)
        unique_chars_in_seg = len(set(seg))
        for m in range(1, unique_chars_in_seg + 1):
            if m * k <= len(seg):
                ans += count_k_freq(seg, m)

    return ans
```

