def find_lexicographically_smallest_beautiful_substring(s: str, k: int) -> str:
    n = len(s)
    indices = [i for i, char in enumerate(s) if char == '1']

    if len(indices) < k:
        return ""

    # Identify all beautiful substrings, track their lengths to find the minimum
    beautiful_substrings = []
    min_len = float('inf')

    for i in range(len(indices) - k + 1):
        start = indices[i]
        end = indices[i + k - 1]
        length = end - start + 1

        if length < min_len:
            min_len = length
            beautiful_substrings = [s[start:end + 1]]
        elif length == min_len:
            beautiful_substrings.append(s[start:end + 1])

    # Return the lexicographically smallest among the ones with min_len
    if not beautiful_substrings:
        return ""

    return min(beautiful_substrings)
