def minimumBeautifulPartitions(s: str) -> int:
    # Precompute powers of 5 in binary form
    # The constraints s.length <= 15 bits, so we only need powers of 5 up to 2^15 - 1
    powers_of_5 = set()
    curr = 1
    while curr < (1 << len(s)):
        powers_of_5.add(bin(curr)[2:])
        curr *= 5

    n = len(s)
    # memo[i] stores the minimum partitions for s[i:]
    memo = {}

    def solve(index):
        if index == n:
            return 0
        if index in memo:
            return memo[index]

        # If leading zero, it's not a beautiful substring
        if s[index] == '0':
            return float('inf')

        res = float('inf')
        # Try all possible substrings starting from index
        for end in range(index + 1, n + 1):
            substring = s[index:end]
            if substring in powers_of_5:
                sub_res = solve(end)
                if sub_res != float('inf'):
                    res = min(res, 1 + sub_res)

        memo[index] = res
        return res

    ans = solve(0)
    return ans if ans != float('inf') else -1
