To solve this problem, we can use Breadth-First Search (BFS) because it is ideal for finding the shortest path in an unweighted graph where each state transition counts as one operation.

```python
from collections import deque

def min_operations(x, y):
    if x == y:
        return 0

    # Using a queue for BFS and a set to keep track of visited states
    queue = deque([(x, 0)])
    visited = {x}

    while queue:
        curr, dist = queue.popleft()

        # Possible next states
        next_states = []
        if curr % 11 == 0:
            next_states.append(curr // 11)
        if curr % 5 == 0:
            next_states.append(curr // 5)
        next_states.append(curr + 1)
        next_states.append(curr - 1)

        for state in next_states:
            if state == y:
                return dist + 1

            # Constraints: target 10^4, keep states reasonably bounded
            # Since we only increment/decrement, we don't need to check 
            # infinite states. 20000 is a safe upper bound.
            if 0 < state < 20000 and state not in visited:
                visited.add(state)
                queue.append((state, dist + 1))

    return -1
```

