def countMatchingSubarrays(nums, pattern):
    """
    Counts the number of subarrays of nums that match the given pattern.
    A subarray nums[i..i+m] matches pattern of size m if for all 0 <= k < m:
    - If pattern[k] == 1, nums[i+k+1] > nums[i+k]
    - If pattern[k] == 0, nums[i+k+1] == nums[i+k]
    - If pattern[k] == -1, nums[i+k+1] < nums[i+k]
    """
    n = len(nums)
    m = len(pattern)
    count = 0

    # The subarray size is m + 1, so the starting index i can range from 0 to n - (m + 1)
    for i in range(n - m):
        match = True
        for k in range(m):
            if pattern[k] == 1:
                if not (nums[i + k + 1] > nums[i + k]):
                    match = False
                    break
            elif pattern[k] == 0:
                if not (nums[i + k + 1] == nums[i + k]):
                    match = False
                    break
            elif pattern[k] == -1:
                if not (nums[i + k + 1] < nums[i + k]):
                    match = False
                    break

        if match:
            count += 1

    return count
