def minimumSum(nums):
    n = len(nums)
    min_sum = float('inf')
    found = False

    # A mountain triplet (i, j, k) requires i < j < k
    # nums[i] < nums[j] and nums[k] < nums[j]
    for j in range(1, n - 1):
        # To minimize the sum, we need the smallest nums[i] where i < j and nums[i] < nums[j]
        # and the smallest nums[k] where k > j and nums[k] < nums[j]

        left_min = float('inf')
        for i in range(j):
            if nums[i] < nums[j]:
                left_min = min(left_min, nums[i])

        right_min = float('inf')
        for k in range(j + 1, n):
            if nums[k] < nums[j]:
                right_min = min(right_min, nums[k])

        if left_min != float('inf') and right_min != float('inf'):
            min_sum = min(min_sum, left_min + nums[j] + right_min)
            found = True

    return min_sum if found else -1
